"""Prepare eight selected whole carrying poses and matched master references."""
from pathlib import Path
from PIL import Image
import json,hashlib
R=Path(__file__).resolve().parents[1];D=R/'character/bill-east-carry-master-v1';D.mkdir(exist_ok=False)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
audit=json.loads((R/'character/bill-east-interact-master-consistency-v1/native/corrected-source-audit.json').read_text(encoding='utf-8'));state=audit['selected']['bare']['carry-east']
idle=R/'character/bill-east-idle-master-motion-v1/frames/idle-east/000.png';ref=Image.new('RGBA',(256,256));ref.alpha_composite(Image.open(idle).convert('RGBA'),(36,52));ref.resize((1024,1024),Image.Resampling.NEAREST).save(D/'idle-reference.png')
master=R/'character/bill-east-walk-master-pilot-v1/original-master.png'
for slot,src in enumerate(state['files']):
 S=D/f'pose-{slot:03}';S.mkdir();p=R/src;Image.open(p).convert('RGBA').resize((1024,1024),Image.Resampling.NEAREST).save(S/'edit-target.png')
 refs=[dict(path=str(q),sha256=sha(q),source=str(s),sourceSha256=sha(s),role=role) for q,s,role in [(S/'edit-target.png',p,'Exact selected carrying pose, cargo and grip geometry'),(D/'idle-reference.png',idle,'Current Bill master idle detail and matte materials'),(master,master,'Original master identity')]]
 prompt=f'''Edit image1 into one complete East-facing Bill carrying the same small grey cargo case, gait phase{slot} of8. Match images2/3's identity and material construction without changing image1's pose, figure size, standing height, limb lengths, build, head placement, spine, legs, near/far limb order, boots or floor contact. Keep cargo case the same size/design/position, level in front of the waist. Exactly two hands securely holding that case, each attached by a continuous glove/cuff/forearm/elbow/upper-arm chain to its actual shoulder. The near red shoulder patch is ON the upper-arm sleeve, connected through the bent elbow to the case-supporting forearm. No chest-grown arm, floating hand, extra waist hand, third arm, disconnected shoulder, oversized bicep, shifted case, fingers penetrating cargo or separated grip. Far arm remains naturally occluded except its genuine case grip. Restore master's matte charcoal-grey quilted padded suit: fine diamond stitching, worn seams, harness straps, belt/pouches, muted red shoulder insignia/chest patch, subdued silver cuff/kneepad/boot hardware. Match current idle's warm readable angular brown-haired bearded face, medium brown hair, matte suit midtones and detail. Not flat near-black fabric, bright glossy suit or exaggerated highlights. Same East profile camera and narrow build. One coherent whole figure, not pasted anatomy. All1024square references have fixed common pivot(512,896); preserve exact placement/stride pose of image1. True transparent RGBA, no background, shadow, halo, checkerboard, blur, text, sheet or extra equipment. Change only material/detail consistency; keep carrying anatomy connected and cargo grip stable.'''
 (S/'prompt.txt').write_text(prompt,encoding='utf-8');(S/'references.json').write_text(json.dumps(refs,indent=2)+'\n',encoding='utf-8')
(D/'selected-contract.json').write_text(json.dumps(state,indent=2)+'\n',encoding='utf-8');(D/'protected-inputs.json').write_text(json.dumps({p:sha(R/p) for p in [state['manifest']]+state['files']},indent=2)+'\n',encoding='utf-8')
print('Eight whole carry targets; selected cargo geometry and master references retained.')
